window.STORY_CHAPTERS["cbfd57a93df734bcc"]={"id":"cbfd57a93df734bcc","lines":[{"uid":"talk.vc.home_wait_leafa_13#originalText","id":"talk.vc.home_wait_leafa_13","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"节分是在驱邪，所以得确实去做才行。","en":"Setsubun is all about exorcising evil spirits, so we have to make sure we toss those beans."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_14#originalText","id":"talk.vc.home_wait_leafa_14","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"来，这是我给你的情人节巧克力。一定要吃喔！","en":"Here... It’s Valentine's chocolate from me. Be sure to eat it, okay?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_15#originalText","id":"talk.vc.home_wait_leafa_15","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"我想要摆设女儿节娃娃，你可以帮我吗？","en":"Hey, can you help me arrange these dolls in the mini-shrine for Hinamatsuri?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_16#originalText","id":"talk.vc.home_wait_leafa_16","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"咦，要给我白色情人节的回礼？真是的，你不用顾虑我啊。不过，还是谢谢你。","en":"Huh? You have a White Day present for me? Aw, you didn't have to! But, thanks!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_17#originalText","id":"talk.vc.home_wait_leafa_17","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"你想说什么谎都可以喔，反正我绝对不会上当！","en":"Lie away, dude! You'll never fool me."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_18#originalText","id":"talk.vc.home_wait_leafa_18","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"呐，如果你有空，我们要不要久违地一家人去旅行？","en":"Hey, if you don't have any plans, wanna go on a family vacation like we used to?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_19#originalText","id":"talk.vc.home_wait_leafa_19","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"哇啊，好大的雨！快让我躲到伞下！……嘿嘿，有点淋湿了。","en":"Agh, it's pouring out there! Lemme share your umbrella! Hehe...oops. We got wet."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_20#originalText","id":"talk.vc.home_wait_leafa_20","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"我去商店街的矮竹上写下愿望了。内容是……秘密！","en":"I wrote down my wish and tied it on the bamboo branch in the shopping district for Tanabata. But my wish is a secret!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_21#originalText","id":"talk.vc.home_wait_leafa_21","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"哼哼，我已经会游泳了，就算是去海水浴场我也不怕！","en":"Well, la-dee-da! I learned how to swim, so bring on the beach days!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_22#originalText","id":"talk.vc.home_wait_leafa_22","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"呐，今晚要不要去赏月？我找到了一个好地点。","en":"Hey, wanna look at the moon tonight? I found a good spot."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_23#originalText","id":"talk.vc.home_wait_leafa_23","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"Trick or Treat！嘿嘿嘿，给我糖果！","en":"Trick or treat! Hehe. Gimme candy!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_24#originalText","id":"talk.vc.home_wait_leafa_24","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"给你，这是赏枫的伴手礼！很小很可爱对吧！","en":"Here, I got you a red leaf! It's so little and cute, isn't it?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_leafa_25#originalText","id":"talk.vc.home_wait_leafa_25","speaker":{"cn":"莉法","en":"Leafa"},"text":{"cn":"圣诞快乐！这个时期会播放圣诞相关歌曲，让人都开心起来了，对吧！","en":"Merry Christmas! Don't you just love hearing all the Christmas music on the radio?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_linel_1#originalText","id":"talk.vc.home_wait_linel_1","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"以前肚子被刺穿的经验太痛苦了。最轻松的方法，还是靠砍头一击毙命呢。","en":"Being stabbed in the stomach hurt dreadfully. The cleanest way to die is by beheading.","ja":"お腹を刺されるのは辛かったです一番楽なのは、首を切って一撃で死ぬことですね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_linel_2#originalText","id":"talk.vc.home_wait_linel_2","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"我虽然不讨厌在房间念书……不过，还是想要一头飞龙。","en":"I don't mind staying in my room and studying, however...I want a flying dragon.","ja":"私は、お部屋でお勉強するのも嫌いじゃないですけど……でも、飛竜はほしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_linel_3#originalText","id":"talk.vc.home_wait_linel_3","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"大家都因为我们是见习生看不起我们，所以我们更要立下功绩才行。","en":"Everyone patronizes me because I'm a trainee. So we need to prove our merit.","ja":"みんな、見習いだからってバカにするんですだから、私たちも功績をあげないと"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_linel_4#originalText","id":"talk.vc.home_wait_linel_4","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"要是毒到死，苏生常常会不管用。所以，毒只用来麻痹。","en":"If poison is used to kill, it often becomes impossible to resurrect the victim. So, my poison merely paralyzes.","ja":"毒で殺すと、蘇生がうまくいかないことが多いのだから、毒は麻痺させるだけ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_linel_9#originalText","id":"talk.vc.home_wait_linel_9","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"怎么了吗？你该不会迷路了吧？","en":"What's wrong? Having doubts?","ja":"どうしたんですか?もしかして、迷いましたか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_linel_10#originalText","id":"talk.vc.home_wait_linel_10","speaker":{"cn":"里涅尔","en":"Linel"},"text":{"cn":"我是……里涅尔。你还记得我吗？","en":"I'm Linel... You remembered me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_linel_11#originalText","id":"talk.vc.home_wait_linel_11","speaker":{"cn":"里涅尔","en":"Linel"},"text":{"cn":"我想知道……你有多强。方便的话，请再来我们这里吧。","en":"I want to know the source of your power... Won't you come visit us again?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lipia_1#originalText","id":"talk.vc.home_wait_lipia_1","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"阁下，请小心暗黑术师。他们总会用些卑鄙手段……","en":"My Lord, please be careful about those Dark Sorcerer. They're a cowardly bunch...","ja":"閣下、暗黒術師にはお気をつけください卑怯な輩ですから……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lipia_2#originalText","id":"talk.vc.home_wait_lipia_2","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"间谍任务就交给我吧。我一定会得到您想要的情报。","en":"If it's intelligence that you're looking for, please leave that to me. I will show you that I can get the info you seek.","ja":"諜報でしたらお任せください必ず、目当ての情報を手に入れてみせます"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lipia_3#originalText","id":"talk.vc.home_wait_lipia_3","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"阁下，如果您有时间的话……我可以跟你说一下话吗？","en":"My Lord, if you happen to have time... Could I talk with you, even if just for a little bit?","ja":"閣下、もしお時間があれば……少しお話をさせていただいてもよろしいですか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lipia_4#originalText","id":"talk.vc.home_wait_lipia_4","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"只要能达成阁下的理想，即使要了我的性命我也在所不惜。","en":"If it helps make my Lord's dream come true, then my life isn't worthless after all.","ja":"閣下の理想をかなえるためなら私の命など惜しくありません"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lipia_9#originalText","id":"talk.vc.home_wait_lipia_9","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"……如果有事请随时吩咐。我会在旁等候。","en":"...If there is anything, please let me know. I will always be at your service.","ja":"……ご用がありましたらいつでもお声がけくださいお側に控えております"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_1#originalText","id":"talk.vc.home_wait_lisbeth_1","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"你的剑真的是用木头做成的吗？又硬又重……我从没看过这种木头耶。","en":"Is your sword really made of wood? It's so hard and heavy... I've never seen wood like this before.","ja":"あんたの剣、本当に木でできてるの?固くて重くて……こんな木見たことないわよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_2#originalText","id":"talk.vc.home_wait_lisbeth_2","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"原来这个世界也有冶炼师啊？希望能跟他们多多讨教。","en":"So, this world also has blacksmiths. I'd love to talk shop with them!","ja":"この世界にも鍛冶師がいるのねいろいろと教えてもらいたいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_3#originalText","id":"talk.vc.home_wait_lisbeth_3","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"反正你是想要我帮你保养武器对吧～真拿你没办法。","en":"Let me guess. You want me to do some weapon maintenance. Oh, fine. If I must, I must.","ja":"どーせ、武器のメンテナンスして欲しいんでしょ～しょうがないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_4#originalText","id":"talk.vc.home_wait_lisbeth_4","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"欸，你等一下有空吗？要不要来逛我的店？","en":"Hey, you free? Wanna come to my shop?","ja":"ねぇ、これから暇?うちの店来ない?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_5#originalText","id":"talk.vc.home_wait_lisbeth_5","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"……我可以坐你旁边吗？","en":"Can I sit next to you?","ja":"……隣座ってもいい?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_6#originalText","id":"talk.vc.home_wait_lisbeth_6","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"欸，我啊，光是在你身边，就会觉得很安心呢。","en":"You know, just being near you really relaxes me.","ja":"ね、あたしさあんたの近くにいるだけでなんか安心しちゃうんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_7#originalText","id":"talk.vc.home_wait_lisbeth_7","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"哇哇哇！我才在想你，本人就出现在眼前，吓了我一大跳啦！","en":"Whoa, man! I was thinking about you, and there you were! Way to scare a girl.","ja":"わわわっ!あんたのこと考えてたら目の前にいてびっくりしたわよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_8#originalText","id":"talk.vc.home_wait_lisbeth_8","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"我是你的专属冶炼师，当然有义务要帮你检查。……不只有装备，全部都是。","en":"I am your exclusive blacksmith. So, I have a duty to check on your weapon. Not just your equipment either, everything.","ja":"あたしはあんたの専属スミスだから、チェックする義務があるの……装備だけじゃなくて、全部"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_9#originalText","id":"talk.vc.home_wait_lisbeth_9","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"发什么呆啊？你很闲的话，要不要跟我出门？","en":"Why are you staring off into space? If you're bored, wanna go somewhere with me?","ja":"なにぼーっとしているのよ暇なんだったら、あたしとどこか出かける? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_10#originalText","id":"talk.vc.home_wait_lisbeth_10","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"辛苦了～我来看看你了。毕竟很久没见嘛。","en":"Hi there, trooper! Thought I'd stop by and say hi, since it's been a while."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_11#originalText","id":"talk.vc.home_wait_lisbeth_11","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"欸欸，现在有空吗？刚好有个不错的任务，要不要一起做？","en":"Hey, are you free right now? A good quest just came in. Wanna do it with me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_12#originalText","id":"talk.vc.home_wait_lisbeth_12","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"恭喜啊～今年一整年也多多指教啰！","en":"Happy New Year! Let's make it a good one."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_13#originalText","id":"talk.vc.home_wait_lisbeth_13","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"有没有不听话的小朋友～！呃，说这句好像不太对呢。","en":"Where' my demon homies at?! Haha, that's not how the Setsubun saying goes, huh."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_14#originalText","id":"talk.vc.home_wait_lisbeth_14","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"来，给你。虽然只是人情巧克力……形式嘛。","en":"Here. Happy Valentine's Day. Purely out of obligation, FYI."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_15#originalText","id":"talk.vc.home_wait_lisbeth_15","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"今天是女儿节嘛，我带了雏米果来。","en":"Since it's Hinamatsuri, I brought special rice crackers for the shrine."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_16#originalText","id":"talk.vc.home_wait_lisbeth_16","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"你是不是有什么东西该给我啊？","en":"So, do you have something to give me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_17#originalText","id":"talk.vc.home_wait_lisbeth_17","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"喂，有一个不认识的女生在叫你喔！……才怪，骗你的啦！","en":"Hey, some hot chick is asking for you! Heh. April Fools!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_18#originalText","id":"talk.vc.home_wait_lisbeth_18","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"不愧是黄金周，到处都人挤人耶。","en":"It's crowded everywhere. That's Golden Week for ya."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_19#originalText","id":"talk.vc.home_wait_lisbeth_19","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"糟糕～我也没带伞。我们两个去躲个雨吧。","en":"Aw, dang. I forgot my umbrella! Maybe we should find a place to wait out the storm."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_20#originalText","id":"talk.vc.home_wait_lisbeth_20","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"今天是七夕嘛，希望天气能放晴呢。","en":"I hope it doesn't rain. Today's Tanabata!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_21#originalText","id":"talk.vc.home_wait_lisbeth_21","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"是说有够热耶，我们找个地方乘凉吧。","en":"Man, is it hot! Let's go somewhere to cool off."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_22#originalText","id":"talk.vc.home_wait_lisbeth_22","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"嘿，我拿芒草来啰。这个摆哪里？","en":"Okay, I got the silver grass. Where should we put it in the display?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_23#originalText","id":"talk.vc.home_wait_lisbeth_23","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"既然要扮装，就大家一起玩吧？材料我这里有喔。","en":"Why don't we all dress up, then? I have enough materials to make costumes."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_24#originalText","id":"talk.vc.home_wait_lisbeth_24","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"啊，你肩膀有片叶子耶。都变得这么红啦……","en":"Oh, look! You've got a leaf on your shoulder. Wow, look at how red it is."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_lisbeth_25#originalText","id":"talk.vc.home_wait_lisbeth_25","speaker":{"cn":"莉兹贝特","en":"Lisbeth"},"text":{"cn":"圣诞快乐！天空下起雪了，似乎会是个白色圣诞节呢。","en":"Merry Christmas! Since it started snowing, we’re in store for a White Christmas."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mary_1#originalText","id":"talk.vc.home_wait_mary_1","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"欢迎回来。……嗯，身上好像都没伤，太好了。","en":"Welcome back. ...Good, looks like you aren't hurt anywhere.","ja":"おかえりなさい!……うん、どこも怪我してないみたいね、よかった"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mary_2#originalText","id":"talk.vc.home_wait_mary_2","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我的天职会是什么呢？因为这双脚，又不能从事动来动去的工作……","en":"I wonder what my Calling will be? Especially since my lame foot limits my ability to move.","ja":"わたしはどんな天職になるのかなこの足じゃ、動き回る仕事はできないし……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mary_3#originalText","id":"talk.vc.home_wait_mary_3","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"不必分心照顾我啊……只要能跟姊姊妳一起在这里生活，我就心满意足了……","en":"It's okay, don't worry about me. I'm just content to live here with you.","ja":"わたしのことは気にしなくていいのに……ふたり一緒にここで暮らせれば、それで……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mary_4#originalText","id":"talk.vc.home_wait_mary_4","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"姊姊真的很喜欢泡澡呢。当然，我也喜欢就是了……","en":"Oh, Sister, you really do love baths, don't you? Well, I love them too, of course.","ja":"お姉ちゃん本当にお風呂が好きねもちろん、わたしも好きだけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mary_5#originalText","id":"talk.vc.home_wait_mary_5","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"今天脚的状况不错，所以我去森林摘了一些水果回来，等等一起吃吧。","en":"My foot is feeling better today, so I went to the forest to forage for fruit. Let's eat some later!","ja":"今日は足の具合がいいから森まで果物を採りにいってきたの後で一緒に食べようね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mary_6#originalText","id":"talk.vc.home_wait_mary_6","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"猎人分了一些猎物给我！今天我会煮大餐喔。啊，不可以偷吃！","en":"A hunter gave me some meat today! I'm going to cook up a big feast for us. Hey! No snacking!","ja":"狩人さんから獲物分けてもらったの!今日はご馳走作るからねあ、つまみ食いはダメだよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mary_7#originalText","id":"talk.vc.home_wait_mary_7","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"使用神圣术不太需要移动身体，所以我想找找看可以在哪里学习。","en":"I've been looking into learning Sacred Arts, since I can do so without needing to move much.","ja":"神聖術ならあんまり動かずに使えるから、習えるところを探してみようと思うの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mary_8#originalText","id":"talk.vc.home_wait_mary_8","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"我自己一个人也不要紧，可是……我会有点寂寞，要快点回来喔。","en":"I'll be fine on my own. But... come back as soon as you can, okay? I get lonely sometimes.","ja":"わたしは、ひとりでも大丈夫でも……ちょっとは寂しいからなるべく早く帰ってきてね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_mary_9#originalText","id":"talk.vc.home_wait_mary_9","speaker":{"cn":"梅雅丽","en":"Mary","ja":"メアリ"},"text":{"cn":"怎么了吗？感觉姊姊没什么精神……如果觉得累了，就要好好休息喔。","en":"What's wrong? You look glum. If you're tired, be sure to rest.","ja":"どうしたの?なんだか元気が無いみたい……疲れてるなら、ちゃんと休んでね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_medina_1#originalText","id":"talk.vc.home_wait_medina_1","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"你为什么这么在意我？你的行动我真的无法理解。","en":"Why do you care about me like that? I don't get you. At all.","ja":"なぜ、こうも私に構う?まったく、お前のことは理解できない"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_medina_2#originalText","id":"talk.vc.home_wait_medina_2","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"我必定会以我这双手洗刷奥尔堤那诺斯家的污名给你们看。","en":"I will wash away the disgraced name of the Orthinanos family with this hand.","ja":"この私の手で、必ずオルティナノス家の汚名をそそいでみせる"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_medina_3#originalText","id":"talk.vc.home_wait_medina_3","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"你妨碍到我修练了。不要一直缠着我。","en":"This is getting in the way of my training. Don't get in the way!","ja":"修練の邪魔だ私にまとわりつくんじゃない"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_medina_4#originalText","id":"talk.vc.home_wait_medina_4","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"我家代代相传的招式绝对不会输给任何人。要是输了，也只是因为我自己训练不足。","en":"No one can defeat my family's techniques. They've been passed down from generation to generation. If I lose, it's because of my lack of training.","ja":"当家が代々受け継いできた技は誰にも負けない。負けるのは私の鍛錬が足りないだけだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_medina_9#originalText","id":"talk.vc.home_wait_medina_9","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"那家伙不在，这附近变得格外安静……感觉心情畅快。嗯。","en":"If that person wasn't here, it would be awfully quiet around these parts... It would be great.","ja":"あいつがいないと、辺りがやけに静かだな……すっきりした気持ちになる。うん"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_nergius_integrator_1#originalText","id":"talk.vc.home_wait_nergius_integrator_1","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"要是敢叫我涅吉，我绝对不会放过你。","en":"Call me Negi one more time, and you will pay dearly.","ja":"私のことをネギと呼んだら決して貴様のことは許さない"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_nergius_integrator_2#originalText","id":"talk.vc.home_wait_nergius_integrator_2","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"你若是理解自己的立场，行事或许就不会这么我行我素……","en":"If you knew your place, you wouldn't act so thoughtlessly or so recklessly.","ja":"自分の立場を理解していれば勝手気ままも大概にしそうなものを……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_nergius_integrator_3#originalText","id":"talk.vc.home_wait_nergius_integrator_3","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"其实我也一样认同你的实力，你的剑技确实不负代表剑士之名。","en":"You are indeed skilled. I have to admit that your skills qualify you to be our swordsman delegate.","ja":"私とてあなたの実力は認めている代表剣士にふさわしい剣技だ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_nergius_integrator_4#originalText","id":"talk.vc.home_wait_nergius_integrator_4","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"萌岚枪绝对不会倒下。而我也一样，绝对不会灰心丧志。","en":"My Budding Storm Spear never falls, and neither shall I.","ja":"萌嵐槍は決して倒れることはないそれはこの私も同じことだ決してくじけたりはせぬ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_nergius_integrator_9#originalText","id":"talk.vc.home_wait_nergius_integrator_9","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"平时不见人影，偶尔却也会这样发呆，你真是叫人摸不透。","en":"I look everywhere for you only to find you here, in a daze. What an elusive fellow you are.","ja":"いつもいないと思えばこうして呆けている時もあるなんと掴みどころのない方だ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_oberon_1#originalText","id":"talk.vc.home_wait_oberon_1","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"强硬地让人服从也是扫兴，让一个讨厌我的人慢慢的对我……那也不错吧。","en":"Even if I am forced to obey, I won't be discouraged. She may dislike me now, but over time... What's wrong with that?","ja":"無理やり従わせても興ざめだ嫌がる相手が徐々にぼくを……それがいいんじゃないか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_oberon_2#originalText","id":"talk.vc.home_wait_oberon_2","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"女王的未婚夫当然是国王才门当户对……特别是比起像那种无聊的家伙呢。","en":"Kings are especially suitable fiancés for a queen... More so than those nobodys.","ja":"女王の婚約者には王こそがふさわしい……アイツのような、馬の骨よりもね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_oberon_3#originalText","id":"talk.vc.home_wait_oberon_3","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"她很美丽……不想让任何人看到她，她是只属于我的东西……","en":"She's so beautiful... I won't let anyone lay eyes on her. She's mine, and mine only...","ja":"彼女は美しい……誰の目にも触れさせたくないぼくだけのものだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_oberon_4#originalText","id":"talk.vc.home_wait_oberon_4","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"茅场学长虽然是个天才，但也是个大笨蛋。他完全没在看现实。","en":"Kayaba is a genius, but a moron as well. He couldn't see reality at all.","ja":"茅場先輩は天才だけど、大馬鹿者さ現実がまったく見えていなかったんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_oberon_9#originalText","id":"talk.vc.home_wait_oberon_9","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"竟然敢无视我，你可真是个蠢蛋。","en":"To ignore someone such as me. Oh dear! You're also such a fool.","ja":"このぼくを無視するとはいやはや君もとんだ愚か者だ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_phillia_1#originalText","id":"talk.vc.home_wait_phillia_1","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"今天要不要去一些没去过的区域喔？说不定会有有趣的东西。","en":"For today, how about we try going somewhere new? There's probably some interesting things there.","ja":"今日はさ、ちょっと知らないエリアに行ってみない?面白い物があるかもしれないし"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_phillia_2#originalText","id":"talk.vc.home_wait_phillia_2","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"现在回想过来，我们也认识很久了啊……一开始相遇时的事，你还记得吗？","en":"Now that I think about it, we've accompanied each other for a long time... Do you remember the first time we met?","ja":"思えば、わたしたちもずいぶん長い付き合いになるよね……最初の出会い、覚えてる?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_phillia_3#originalText","id":"talk.vc.home_wait_phillia_3","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"呐，你已经决定了今天要做什么了吗？如果有空，要不要跟我组个队？","en":"Hey, do you have any plans for today? If it's ok with you, would you like to form a party with me?","ja":"ね、今日の予定は決まってる?よかったら、わたしとパーティ組んでくれないかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_phillia_4#originalText","id":"talk.vc.home_wait_phillia_4","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"呐呐，我听说有宝藏！要不要一起去调查看看！","en":"Hey hey! Rumor has it, there's treasure! Do you want to go looking for it together?","ja":"ねえねえ、お宝があるって噂を聞いたの!一緒に調べてみようよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_phillia_9#originalText","id":"talk.vc.home_wait_phillia_9","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"……你好像很忙。没关系，我一个人也没问题的。","en":"...You seem pretty busy, huh. I'm open to it.","ja":"……なんだか忙しいみたいねうん、わたしは大丈夫だから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_premiere_1#originalText","id":"talk.vc.home_wait_premiere_1","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"要是有时间的话，请再教我战斗的秘诀吧。","en":"If you happen to have any time, could you teach me some battle tricks again?","ja":"時間があったら、また戦闘のコツを教えてください"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_premiere_2#originalText","id":"talk.vc.home_wait_premiere_2","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"当我觉得寂寞的时候，你总是会出现在我面前。呵呵……现在也是。","en":"You always came whenever I felt lonely. Just like now. Hehe...","ja":"私が寂しいと思った時はいつもあなたが来てくれましたふふ……今も、そうです"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_premiere_3#originalText","id":"talk.vc.home_wait_premiere_3","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"总觉得，好像饿了。要不要吃个便当？","en":"I'm kind of hungry. Would you like to eat some lunch box?","ja":"なんだか、お腹がすきましたお弁当、食べませんか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_premiere_4#originalText","id":"talk.vc.home_wait_premiere_4","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"跟你在一起，就能学到很多东西。所以，想常时跟你在一起。","en":"I get to learn so much whenever I am with you. That's why I always want to be with you.","ja":"あなたと一緒にいると様々なことを学習できますだから、いつでも一緒にいたい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_premiere_9#originalText","id":"talk.vc.home_wait_premiere_9","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"听我说……其实也没什么。我只是在想你是不是有哪里不舒服呢？","en":"I mean... No, perhaps are you feeling ill?","ja":"あの……いえ、もしかしたらどこか調子が悪いのですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rain_1#originalText","id":"talk.vc.home_wait_rain_1","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"怎么了？该不会，你刚好在找我吗？","en":"What's going on? Could it be that you're looking for me?","ja":"どうしたの?もしかして、わたしを探してたりして?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rain_2#originalText","id":"talk.vc.home_wait_rain_2","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"呵呵，有伙伴的感觉真不错！","en":"Hehe. Having company isn't such a bad thing!","ja":"ふふ、仲間がいるってなんかいいよね!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rain_3#originalText","id":"talk.vc.home_wait_rain_3","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"下次如果有时间，你能听我唱歌吗？我想让你听听。","en":"Next time when you have time, can you listen to my song? I want you to hear it.","ja":"今度、時間がある時にわたしの歌、聞いてくれる?君に聞いてほしいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rain_4#originalText","id":"talk.vc.home_wait_rain_4","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"偶像活动……我当然有在努力了！我一定会实现给你看的！","en":"The life of an idol... Of course I'm working hard! It's what I've always wished for!","ja":"アイドル活動……もちろん頑張ってるよ!絶対叶えてみせるんだから!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rain_9#originalText","id":"talk.vc.home_wait_rain_9","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"……你是不是在想些很难的事啊？如果想要转换心情的话，唱歌很有用喔！","en":"...Are you thinking about something difficult? If you want to lighten up your mood why not try singing!","ja":"……何か難しいこと考えてる?もし気分を変えたいなら歌を歌ってみるといいよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_raios_1#originalText","id":"talk.vc.home_wait_raios_1","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"乡下人不懂道理也是没办法的事，我们必须加以引导才行。","en":"You're a fresh-off-the-boat bumpkin, so your ignorance is inevitable. You need our guidance.","ja":"田舎者が道理を知らぬのは仕方のないことだ我々が導いてやらんとな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_raios_2#originalText","id":"talk.vc.home_wait_raios_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"真受不了，不懂自己身分的人真是令人头疼。","en":"Oh, bother. I don't want to waste my time on a bastard with questionable lineage.","ja":"やれやれ、身分をわきまえぬ輩にも困ったものだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_raios_3#originalText","id":"talk.vc.home_wait_raios_3","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"必须稍微练一下套路才行。虽然我也不认为自己会落败。","en":"You need to practice your form a little. Though I doubt I'll fall behind you.","ja":"少しは型の稽古もやらないとなこの私が後れを取るとも思えんが"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_raios_4#originalText","id":"talk.vc.home_wait_raios_4","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"对说话猖狂的家伙，我要行使裁决权。","en":"I have the right to pass judgement on impudence.","ja":"生意気なことを言うヤツには裁決権を行使してやる"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_raios_9#originalText","id":"talk.vc.home_wait_raios_9","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"那么，既然拿到了好酒，就来浅尝几口吧。","en":"Well, I think I'll have a drink. I just got in some nice wine.","ja":"さて、いい酒が入ったから少し嗜むとするか"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_raios_10#originalText","id":"talk.vc.home_wait_raios_10","speaker":{"cn":"莱欧斯","en":"Raios"},"text":{"cn":"我的名字是莱欧斯‧安提诺斯。你不会忘了吧？","en":"My name is Raios Antinous. Don't insult me by saying you forgot it?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_renri_1#originalText","id":"talk.vc.home_wait_renri_1","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"喔，是你呀。能在这里见到你，看来我今天运气不错。","en":"It's you. Looks like it's my lucky day meeting you here.","ja":"やあ、君かここで会えるなんて、今日は運がいいみたいだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_renri_2#originalText","id":"talk.vc.home_wait_renri_2","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"像我这种失败作，多少也得锻炼一下。不然会追不上大家的。","en":"A failure like me needs to get better, even if it's just by a little. So that I don't leave everyone behind.","ja":"僕みたいな失敗作は少しでも鍛えないとねみんなに置いて行かれないために"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_renri_3#originalText","id":"talk.vc.home_wait_renri_3","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"如、如……如果可以的话，下次要不要去喝杯茶？如果不想的话，也没关系。","en":"I-If... it's ok with you. How about we get some tea next time? That is, if you're fine with it.","ja":"よ、よ……よかったら今度お茶でもどうかな?イヤだったら、その、いいんだけど"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_renri_4#originalText","id":"talk.vc.home_wait_renri_4","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"果然，面对敌人还是会害怕。但是，也不能输给那份恐惧……","en":"Just as I thought. Going up against enemies is scary. But, I won't give in to that fear... ","ja":"やっぱり、敵と向き合うのは怖いよでも、その恐怖に負けちゃいけないんだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_renri_9#originalText","id":"talk.vc.home_wait_renri_9","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"在这样安静的环境下，我总会感觉到内心深处有一个很大的洞。不被填满、巨大的洞。","en":"When it's quiet like this I can feel a big hole within the darkest reaches of my heart. It's large and very deep.","ja":"こうやって静かにしていると胸の奥に大きな穴を感じるんだ埋まらない、とても大きな穴を"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_1#originalText","id":"talk.vc.home_wait_ronye_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"本日的清扫已经顺利完成！","en":"I have finished today's cleaning, without delay!","ja":"本日の清掃、滞りなく完了しました! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_2#originalText","id":"talk.vc.home_wait_ronye_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"这个《艾恩葛朗特流》，您是在哪里学到的呢？","en":"Where did you learn Aincrad Style?","ja":"《アインクラッド流》ってどこで教えてもらったんですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_3#originalText","id":"talk.vc.home_wait_ronye_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"之前您给我的跳鹿亭蜂蜜派，非常好吃喔！","en":"Those honey pies from the Prancing Deer were so delicious!","ja":"この間いただいた、跳ね鹿亭の蜂蜜パイ……すっごくおいしかったです!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_4#originalText","id":"talk.vc.home_wait_ronye_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"能被选为学长的随侍，我真的很开心！","en":"I am so honored to be your page!","ja":"先輩の傍付きに選んでいただけてとってもうれしいです! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_5#originalText","id":"talk.vc.home_wait_ronye_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"您今天要教我如何承受《瑙鲁基亚流》的攻击对吧！麻烦您了！","en":"So, you're teaching me Norkian Style today! I look forward to learning from you.","ja":"今日は《ノルキア流》の受け方を教えていただけるんですよね! よろしくお願いします! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_6#originalText","id":"talk.vc.home_wait_ronye_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我第一次看到纯黑的剑。请问是用什么做成的呢？","en":"I've never seen a black sword before. What's it made of?","ja":"真っ黒な剣、って初めて見ました何でできているんですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_7#originalText","id":"talk.vc.home_wait_ronye_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"那个！今天也您请务必训练我！","en":"Excuse me! Will you please train me again today?","ja":"あの!今日もぜひ、私に稽古をつけてください!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_8#originalText","id":"talk.vc.home_wait_ronye_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"最近只要来学长的房里，我就会觉得心跳加速。呃，不、不是因为紧张，那个……","en":"Lately I've been nervous whenever I enter your room. N-no, I'm not scared, exactly. I'm, uh...","ja":"先輩のお部屋に来ると、最近はドキドキしちゃうんですい、いえ、緊張ではなくて、その……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_9#originalText","id":"talk.vc.home_wait_ronye_9","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"没问题的！像这样等待也是随侍的任务！","en":"Don't worry! Waiting like this is also a page's duty!","ja":"大丈夫です! こうして待つのも、傍付きの任務ですから! "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_10#originalText","id":"talk.vc.home_wait_ronye_10","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"罗妮耶‧阿拉贝鲁，前来报到！","en":"Ronie Arabel, reporting for duty!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_11#originalText","id":"talk.vc.home_wait_ronye_11","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"总觉得好久不见了。《艾恩葛朗特流》的训练，再麻烦您费心了！","en":"I haven't seen you in a while. I would love some more Aincrad Style training, please!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_12#originalText","id":"talk.vc.home_wait_ronye_12","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"罗妮耶‧阿拉贝鲁，前来拜年了！今年也请多多指教！","en":"Your Ronie Arabel formally wishes you a Happy New Year!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_13#originalText","id":"talk.vc.home_wait_ronye_13","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"我听说需要豆子，所以就带了许多过来！","en":"You requested beans, so I brought many!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_14#originalText","id":"talk.vc.home_wait_ronye_14","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"我听说今天是送重要的人点心的日子，请您收下这个！","en":"I heard today is a day where we give candy to someone special. So...here you go!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_15#originalText","id":"talk.vc.home_wait_ronye_15","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"雪洞灯？正在发光的这盏灯叫做雪洞灯吗？","en":"Bonbori? This paper lamp is called a \"Bonbori\"?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_16#originalText","id":"talk.vc.home_wait_ronye_16","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"不、不是这样的！我绝对不是想要回礼才……","en":"Oh, I couldn't! I don't deserve a return gift..."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_17#originalText","id":"talk.vc.home_wait_ronye_17","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"学长！说什么边倒立边战斗才是《艾恩葛朗特流》，根本是在说谎嘛。","en":"Mentor! Fighting whilst facing backwards... Surely that isn't an Aincrad Style move!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_18#originalText","id":"talk.vc.home_wait_ronye_18","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"学长，您在安息日有安排进程吗？可以的话，要不要跟我……","en":"Do you have any plans for the coming days of rest? If you don't mind, you and I could, uh..."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_19#originalText","id":"talk.vc.home_wait_ronye_19","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"突然下起雨来了呢，连鞋子都湿透了。","en":"It's suddenly started to rain. My shoes are soaked through!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_20#originalText","id":"talk.vc.home_wait_ronye_20","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"学长您许了什么愿望呢？","en":"What did you wish for, Mentor?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_21#originalText","id":"talk.vc.home_wait_ronye_21","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"今天好热耶～像这种天气，要不要去河边乘个凉呢？","en":"What hot weather we're having. Would you like to cool off at the river?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_22#originalText","id":"talk.vc.home_wait_ronye_22","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"月亮真美呢，学长。……咦，为什么您会那么害羞呢？","en":"The moon sure is beautiful tonight. Isn't it romantic... Huh? Why are you blushing?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_23#originalText","id":"talk.vc.home_wait_ronye_23","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"我拿到好多点心，要不要一起吃呢，学长！","en":"I got a lot of candy, so I'd like to share it with you, Mentor!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_24#originalText","id":"talk.vc.home_wait_ronye_24","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"现在正是收获的季节，所以餐点特别好吃喔。我们一起去品尝吧。","en":"Everything is so delicious during harvest season! Let's go out and eat something."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_ronye_25#originalText","id":"talk.vc.home_wait_ronye_25","speaker":{"cn":"罗妮耶","en":"Ronie"},"text":{"cn":"学长，外面下雪了耶！要不要稍微出去看看呢？","en":"Mentor, look! It's snowing! Want to go play in the snow?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rosalia_1#originalText","id":"talk.vc.home_wait_rosalia_1","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"差不多该发现美味的猎物了吧？","en":"Have you found any delicious prey?","ja":"そろそろおいしい獲物は見つかったのかしら?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rosalia_2#originalText","id":"talk.vc.home_wait_rosalia_2","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"我的伙伴里不需要软弱的人。你要更无情一点。","en":"There's no room for weaklings in my party. Please, take this more seriously.","ja":"アタシの仲間に軟弱者はいらないのもっと非情になりなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rosalia_3#originalText","id":"talk.vc.home_wait_rosalia_3","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"可别劳烦我动手啊。我必须保持绿色才行。","en":"Don't make me get blood on my hands. I have to stay a green player.","ja":"アタシの手を煩わせるんじゃないよ?アタシはグリーンでいなきゃいけないんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rosalia_4#originalText","id":"talk.vc.home_wait_rosalia_4","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"什么正义还法律的，蠢到家了。你应该没有在拘泥那些吧？","en":"Justice? Law? What a load of crap. I hope you're not into that stuff.","ja":"正義とか法律とか、ばっかみたいあんたはそんなことにこだわってないでしょうね?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rosalia_9#originalText","id":"talk.vc.home_wait_rosalia_9","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"你发什么呆啊？还不快去赚钱回来。","en":"Why are you spacing off? Hurry up and earn your keep.","ja":"なにぼーっとしてるのよさっさと稼いで来なさい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_rosalia_10#originalText","id":"talk.vc.home_wait_rosalia_10","speaker":{"cn":"罗莎莉雅","en":"Rosalia"},"text":{"cn":"哎呀，好久不见。偶尔来露个脸吧。","en":"Oh, hi. Maybe don't ghost me next time?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sachi_1#originalText","id":"talk.vc.home_wait_sachi_1","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"没想到还能见到你……好像作梦一样。","en":"Wow, I get to be with you again... It feels like a dream.","ja":"また君に会えるなんて……なんだか夢みたい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sachi_2#originalText","id":"talk.vc.home_wait_sachi_2","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"可以教我怎么用剑吗？我想尽可能变强……","en":"Will you teach me how to use a sword? I want to pull my own weight, in any way I can.","ja":"剣の使い方、教えてくれるかな少しでも、強くなりたいから……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sachi_3#originalText","id":"talk.vc.home_wait_sachi_3","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"跟怪物战斗的时候还是有点恐怖。不过，只要跟你在一起，就没有问题。","en":"When monsters show up, I do get scared, but I'll be fine as long as you're with me.","ja":"やっぱり、モンスターと戦う時はちょっと怖いなでも、君と一緒なら大丈夫"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sachi_4#originalText","id":"talk.vc.home_wait_sachi_4","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"希望有一天，我们在现实世界也可以相见……说笑的。","en":"Someday, I'd love to meet up with you in the real world... Haha. Silly, I know.","ja":"いつの日か、現実の世界でも会えたらいいな……なんて"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sachi_9#originalText","id":"talk.vc.home_wait_sachi_9","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"……呵呵，不知不觉就盯着你看了。对不起喔。","en":"Hehe...sorry. Didn't mean to stare.","ja":"……ふふ、つい見つめちゃったごめんね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sachi_10#originalText","id":"talk.vc.home_wait_sachi_10","speaker":{"cn":"幸","en":"Sachi"},"text":{"cn":"你、你好，好久没看到你……我好开心。","en":"H-hello! So good to see you after all this time."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sachi_11#originalText","id":"talk.vc.home_wait_sachi_11","speaker":{"cn":"幸","en":"Sachi"},"text":{"cn":"呵呵，不论我在哪里，你都会找到我呢。","en":"Hehe, no matter where I am, I'm always able to find you."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sakuya_1#originalText","id":"talk.vc.home_wait_sakuya_1","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"你终于有意思和我把酒言欢了吗？","en":"Are you finally up for having a drink with me?","ja":"そろそろ、私と酒を酌み交わす気になってくれたかい?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sakuya_2#originalText","id":"talk.vc.home_wait_sakuya_2","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"我可是还没放弃你喔？要是你有那个意思，随时都可以来跟我说。","en":"I haven't given up on you yet. When you change your mind, give me a holler.","ja":"私はまだ君を諦めていないぞ?その気になったら、いつでも声をかけてくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sakuya_3#originalText","id":"talk.vc.home_wait_sakuya_3","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"我偶尔也试着像你一样，四处自由活动好了。","en":"Maybe I should take a cue from you and wander around freely for once.","ja":"私もたまには、君のように自由に動き回ってみるかな"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sakuya_4#originalText","id":"talk.vc.home_wait_sakuya_4","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"我很开心能再次跟你并肩作战。当然一方面是因为你很强……但更多原因是来自我的私情。","en":"I'm happy to fight by your side again. Naturally, it's partly because you're so powerful... But I also just appreciate your company.","ja":"また君と共に戦えて嬉しいもちろん君の強さもそうだが……もっと個人的な事情で、な"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sakuya_9#originalText","id":"talk.vc.home_wait_sakuya_9","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"你在想事情吗？如果有我帮得上忙的地方，请随时告诉我。","en":"Something on your mind? Let me know if there's any way I can help.","ja":"なにか考え事か?私で力になれることがあったらいつでも言ってくれ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sakuya_10#originalText","id":"talk.vc.home_wait_sakuya_10","speaker":{"cn":"朔夜","en":"Sakuya"},"text":{"cn":"嗨，是你，好久不见。真开心能见到你。","en":"Hey, kid. Long time no see. Good to see you."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_scheta_1#originalText","id":"talk.vc.home_wait_scheta_1","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……找我有事吗？","en":"...Do you need something from me?","ja":"……私になにか用事?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_scheta_2#originalText","id":"talk.vc.home_wait_scheta_2","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"我不想看到人。因为他们被我斩断的样子会在我脑海中浮现……","en":"I don't want to look. Their mangled bodies will haunt my thoughts...","ja":"見たくないの切断された姿が頭に浮かんでしまうから……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_scheta_3#originalText","id":"talk.vc.home_wait_scheta_3","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"你不要再管我，去跟其他人说说话怎样？","en":"I don't mind myself, but how about talking to someone else?","ja":"私なんかに構ってないでほかの人と話をしたらどう?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_scheta_4#originalText","id":"talk.vc.home_wait_scheta_4","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"决胜负……？现在的你看起来好像还是很软弱……","en":"Victory...? You seem soft, just now...","ja":"勝負……?今のあなたは柔らかそうだけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_scheta_9#originalText","id":"talk.vc.home_wait_scheta_9","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……像这样保持距离，对我来说最好不过。","en":"...Keeping your distance from me will be the biggest help.","ja":"……そうして距離を置いてもらえるのが、一番助かる"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_selka_1#originalText","id":"talk.vc.home_wait_selka_1","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"啊～我当见习生的日子能不能快点结束啊。","en":"Awww, I wonder when my trainee period will be over?","ja":"あー、あたしも早く見習い期間が終わらないかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_selka_2#originalText","id":"talk.vc.home_wait_selka_2","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"呐，挥剑好玩吗？我没什么做过那种事……","en":"Tell me, is sword-fighting fun? I've never really tried it...","ja":"ねえ、剣を振るのって楽しい?あたしは、あんまりそういうのやったことなくて……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_selka_3#originalText","id":"talk.vc.home_wait_selka_3","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"你到底是博学多闻，还是孤陋寡闻呢？我都搞不清楚了。","en":"Sometimes, I'm not sure whether you're a genius or a fool.","ja":"あなたって、物知りなのか物知らずなのか、よくわからないわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_selka_4#originalText","id":"talk.vc.home_wait_selka_4","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"我跟姊姊不一样……不过，我希望能多少跟她相似一些。","en":"I'm not as good as my sister... But I'd at least like to get closer to her level.","ja":"あたしは姉さまとは違う……けど、せめて近づくくらいはしたいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_selka_9#originalText","id":"talk.vc.home_wait_selka_9","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"呐，接下来要做什么呢？","en":"So, what's next?","ja":"ねえ、これからどうするの?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_selka_10#originalText","id":"talk.vc.home_wait_selka_10","speaker":{"cn":"赛鲁卡","en":"Selka"},"text":{"cn":"你看，我带便当过来啰。我对这次的成品很有自信。","en":"I brought your lunch! I'm really proud of this one."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_selka_11#originalText","id":"talk.vc.home_wait_selka_11","speaker":{"cn":"赛鲁卡","en":"Selka"},"text":{"cn":"总觉得好久不见了。呐，你不想再住教会了吗？其实你什么时候来都可以啊……","en":"I haven't seen you in a while. So, why don't you come live at the Church? Then I could see you all the time."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_seven_1#originalText","id":"talk.vc.home_wait_seven_1","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"哟！碰到你真好！你能稍微帮忙做一下研究吗？","en":"Privyet! What perfect timing! Would you mind helping me out a little with my research?","ja":"プリヴィエート!ちょうどいいところにいたわね!ちょっと、研究を手伝ってくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_seven_2#originalText","id":"talk.vc.home_wait_seven_2","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"嗯，研究还在继续喔。VR世界真的是博大精深。","en":"Yes, I'm also continuing research. The VR world is so interesting, don't you think?","ja":"うん、研究も続けてるわVRの世界って、なかなか興味深いのよね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_seven_3#originalText","id":"talk.vc.home_wait_seven_3","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"任务？我就先不做了。我今天决定了要在这边悠闲地过。","en":"Quest? I'll have to pass. I decided that I'll be taking it easy today.","ja":"クエスト?あたしはパス。今日はこっちでゆっくりするって決めたの"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_seven_4#originalText","id":"talk.vc.home_wait_seven_4","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"和打从心底信赖的人像这样悠闲地过日子，真的很开心。","en":"It really is fun to be able to do this and relax with someone you can trust.","ja":"本当に信頼できる人とこうしてのんびりするのはとても楽しいわ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_seven_9#originalText","id":"talk.vc.home_wait_seven_9","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"偶尔冥想一下也很重要……但我在你身边的时候，不用冥想也没关系吧？","en":"In time, meditation is also necessary... but when I'm by your side don't you think you're fine without?","ja":"時には瞑想も必要だけど……あたしがそばにいる時にしなくてもいいんじゃない?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shasta_1#originalText","id":"talk.vc.home_wait_shasta_1","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"我只要一天不挥剑，就静不下心来。这也是我的性格，原谅我吧。","en":"Apologies. I need to swing my sword at least once a day or I won't feel right. It's my nature to do so.","ja":"日に一度は剣を振らないと落ち着かないのでなこれも性分だ、許せ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shasta_2#originalText","id":"talk.vc.home_wait_shasta_2","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"这话也只能在你面前说，要是有一天可以和人界和解的话……这个国家或许会变得更适合人们居住吧。","en":"I can only say this to you, but if one day we can reach a compromise with the Human Empire... Life would be easier in this country.","ja":"お前の前でしか言えぬことだがいつか人界と和解できれば……この国も住みやすくなるだろう"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shasta_3#originalText","id":"talk.vc.home_wait_shasta_3","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"集成骑士团长……那家伙的剑超越了人类智能。要追上他需要非比寻常的努力才行。","en":"The commander of the Integrity Knights... His sword transcends human intellect. Following it requires extraordinary effort. ","ja":"整合騎士団長……奴の剣は人智を越えている。追いつくには尋常ならざる努力が必要だ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shasta_4#originalText","id":"talk.vc.home_wait_shasta_4","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"暗黑术师，再加上哥布尔、食人鬼……他们是比人类更麻烦的存在。","en":"Dark Sorcerers have Goblins, Ogres... Their existence is more troublesome than the humans.","ja":"暗黒術師にゴブリン、オーガ……人間よりも厄介なのは奴らの存在だ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_shasta_9#originalText","id":"talk.vc.home_wait_shasta_9","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"你在想事情吗？如果有我帮得上忙的地方，随时告诉我吧。","en":"Something on your mind? If I can be of any assistance, don't be afraid to ask for help.","ja":"何か考え事か?俺が力になれることであればなんでも言うがいい"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_1#originalText","id":"talk.vc.home_wait_silica_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"如果进到修剑学院的话……我会变得比现在更强吗……","en":"Swordcraft Academy... I wonder if attending will make me stronger than now...","ja":"修剣学院……そこに入ればあたしも今より強くなれるかなあ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_2#originalText","id":"talk.vc.home_wait_silica_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"不知道毕娜长大后，愿不愿意让我骑在背上？","en":"When Pina gets big, do you think she'll let me ride her?","ja":"ピナも大きくなったら、背中に乗せてくれるかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_3#originalText","id":"talk.vc.home_wait_silica_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"我到现在还是不敢相信，这里是虚拟实境的世界。","en":"I still can't believe this is a virtual world.","ja":"ここが仮想現実の世界だなんて今でも信じられません"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_4#originalText","id":"talk.vc.home_wait_silica_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"如果有禁忌目录的话，是不是就不会有橘色公会了呢……我不禁在思考这种问题。","en":"If there's a Taboo Index, I wonder if there's no Orange Guild here... I can't help but wonder it, you know?","ja":"禁忌目録があればオレンジギルドもないのかな……なんて、思っちゃいました"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_5#originalText","id":"talk.vc.home_wait_silica_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"……我、我可以再靠近你一点吗？","en":"Can I, um...come a bit closer?","ja":"……も、もうちょっと近くにいってもいいですか?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_6#originalText","id":"talk.vc.home_wait_silica_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"不论在哪个世界，都会有人钻规矩的漏洞呢……","en":"In every world, there are people who bend the rules.","ja":"どこの世界にもルールの抜け道を利用する人がいるんですね……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_7#originalText","id":"talk.vc.home_wait_silica_7","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"请问……今天的我如何呢？其实我有剪了一点浏海。会、会很奇怪吗……？","en":"So...how do I look? You see, I cut my bangs today. Do I look...weird?","ja":"あの…今日のあたしどうですか?実は前髪を少し切ったんですへ、変じゃないですか……?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_8#originalText","id":"talk.vc.home_wait_silica_8","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那、那个……什么时候都行，呃……两、两个人一起去……买东西、之类的吧……","en":"So, yeah, like, anytime you want to go shopping... I'm totally cool with that.","ja":"あ、あの……いつでもいいのでその……お、お買い物とか……ふたりで行って、ください……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_9#originalText","id":"talk.vc.home_wait_silica_9","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"请、请问……不，什么事也没有。","en":"N-never mind! Forget I said anything.","ja":"あ、あの……いえ、なんでもありません"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_10#originalText","id":"talk.vc.home_wait_silica_10","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"你、你好……我有打扰到你吗？","en":"Hello! Is...this a bad time?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_11#originalText","id":"talk.vc.home_wait_silica_11","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"有点久没见了呢，你过得还好吗？","en":"I haven't seen you in a while. How have you been?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_12#originalText","id":"talk.vc.home_wait_silica_12","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"新年快乐。打扰了，我来拜年了。","en":"Happy New Year! Just came to tell you that."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_13#originalText","id":"talk.vc.home_wait_silica_13","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"今天是节分呢。要不要一起撒豆子呢？","en":"It's Setsubun! Would you like to throw beans with me?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_14#originalText","id":"talk.vc.home_wait_silica_14","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"那、那个……这个巧克力给你！","en":"Um, here, I got you some chocolates!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_15#originalText","id":"talk.vc.home_wait_silica_15","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"因为女儿节是女孩子的节日，我小时候都过得很开心。","en":"I had a lot of fun with Hinamatsuri when I was a little girl, since it's a festival for little girls."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_16#originalText","id":"talk.vc.home_wait_silica_16","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"咦，我也有东西可以收吗？谢……谢谢你！","en":"Huh? You have a gift for me, too? Oh...thank you so much!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_17#originalText","id":"talk.vc.home_wait_silica_17","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"呵呵，到处都在举办愚人节的活动呢。","en":"Hehe, I'm seeing April Fool's events all over the place."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_18#originalText","id":"talk.vc.home_wait_silica_18","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"请、请问……你黄金周已经有安排了吗？","en":"So, um...do you have plans for Golden Week?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_19#originalText","id":"talk.vc.home_wait_silica_19","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"啊，如果你没带伞的话，要不要一起撑呢？","en":"Oh! Uh, if you don't have an umbrella, want to share mine?"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_20#originalText","id":"talk.vc.home_wait_silica_20","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"等等，毕娜！不要拿走那张短签～","en":"Wait, Pina! Don't fly away with my wish!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_21#originalText","id":"talk.vc.home_wait_silica_21","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"那个……你流了很多汗呢。我帮你擦一擦，麻烦稍微蹲下来一点。","en":"So, uh...you're really sweaty. Crouch down and I'll towel you off."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_22#originalText","id":"talk.vc.home_wait_silica_22","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"我做了好多团子。我很喜欢这种团子呢。","en":"I got lots of rice dumplings! I really love them."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_23#originalText","id":"talk.vc.home_wait_silica_23","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"T、Trick or Treat……请不要盯着我看。扮装太令人害羞了……","en":"So, uh, trick or treat? Please, don't stare. I'm not very comfortable in this costume."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_24#originalText","id":"talk.vc.home_wait_silica_24","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"大家带着各自的便当，一起去赏枫吧。","en":"Let's get the gang together for a picnic under the autumn leaves!"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_silica_25#originalText","id":"talk.vc.home_wait_silica_25","speaker":{"cn":"西莉卡","en":"Silica"},"text":{"cn":"圣诞快乐！这是圣诞礼物。你愿意收下吗？","en":"Merry Christmas! I got you a present."},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_1#originalText","id":"talk.vc.home_wait_sinon_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"真是的，你总是惹出一堆麻烦事。","en":"Jeez, it's one annoying task after another...","ja":"まったく、本当にいつも厄介事ばかりなのね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_2#originalText","id":"talk.vc.home_wait_sinon_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"不像现实，也不像油料跟火药，这个世界的气味很不可思议呢。","en":"It has a mysterious smell to it. It's not like the real world, or the world of gas and gunpowder.","ja":"現実とも、油や火薬とも違う不思議な匂いのする世界ね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_3#originalText","id":"talk.vc.home_wait_sinon_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"在这里，我的《天职》大概是《猎人》吧。如果有《狙击手》就好了。","en":"I guess my \"Calling\" in this world would probably be a \"hunter.\" Too bad \"sniper\" isn't an option.","ja":"ここでの私の《天職》は《狩人》ってところかしら《狙撃手》があればいいんだけどね"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_4#originalText","id":"talk.vc.home_wait_sinon_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"如果你不见，我在《BoB》就头痛了。所以我才来了。","en":"I came here to find you to make sure I don't lose you. \"BoB\" would be tough without you.","ja":"もしあんたがいなくなっちゃったら《BoB》で困るからだから迎えに来たのよ"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_5#originalText","id":"talk.vc.home_wait_sinon_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"该不会……你连神圣术的攻击都能用剑劈开吧？","en":"Just a theory, but can you repel Sacred Arts attacks with your sword?","ja":"もしかしたら、神聖術の攻撃だって剣で叩き切れるんじゃない? "},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_6#originalText","id":"talk.vc.home_wait_sinon_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"剑术大会以外，有没有射击大会啊？","en":"I wonder if they have a shooting tournament as well as a sword tournament.","ja":"剣術大会じゃなくて射撃の大会とかはないのかしら"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_7#originalText","id":"talk.vc.home_wait_sinon_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你在那里啊。我、我好想你……","en":"Oh, there you are. G-good to see you...","ja":"そこにいたのねあ、会いたかったわ……"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_8#originalText","id":"talk.vc.home_wait_sinon_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"欸，再带我出去啦。……就像那时候一样，我们双载。","en":"Hey, can you take me out again like last time? With us on the same bike...","ja":"ねえ、また私を外に連れ出してよ……あの時みたいに、ふたり乗りで"},"kind":"dialogue"},{"uid":"talk.vc.home_wait_sinon_9#originalText","id":"talk.vc.home_wait_sinon_9","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"怎么，你累了吗？那就稍微休息一下吧。","en":"Oh, are you tired? Wanna take a break together?","ja":"なに、疲れたの? だったら、少し休みましょうか"},"kind":"dialogue"}]};
